{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Absolute oral bioavailability of tolfenamic acid in healthy volunteers averaged 60% across 100–800 mg oral doses versus intravenous dosing, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib absolute oral bioavailability was 25.3% (geometric mean) in healthy subjects using an intravenous microtracer, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C10"],
      "claim": "6-MNA absolute oral bioavailability was approximately 35% in healthy volunteers after nabumetone 1 g versus intravenous 6-MNA, supporting F ≥ 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All transferred evidence molecules show oral bioavailability values ≥23.7%, with most absolute measurements in healthy subjects or patients ranging from about 25% to 100%; therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "Molecule 7 includes a record for abemaciclib (C27) under acalabrutinib; this provenance conflict was discounted.",
    "Some records are qualitative or use unspecified bioavailability types, but numeric absolute measurements dominate the evidence."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C30", "C01", "C10"],
  "revision_action": "initial",
  "supportive_card_ids": ["C30", "C01", "C10"]
}

